/// Adds the route of every contract component `control-plane` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn control_plane_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::ControlPlane + Send + Sync + 'static,
    H: ControlPlaneHooks,
{
    let routes = serve_provision_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_get_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_resolve_host(routes, service.clone(), hooks.clone());
    let routes = serve_suspend_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_resume_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_export_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_delete_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_cancel_tenant_deletion(routes, service.clone(), hooks.clone());
    let routes = serve_restore_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_start_sandbox(routes, service.clone(), hooks.clone());
    let routes = serve_keep_sandbox(routes, service.clone(), hooks.clone());
    let routes = serve_bind_domain(routes, service.clone(), hooks.clone());
    let routes = serve_remove_domain_binding(routes, service.clone(), hooks.clone());
    let routes = serve_change_plan(routes, service.clone(), hooks.clone());
    let routes = serve_find_due_tenants(routes, service.clone(), hooks.clone());
    let routes = serve_record_next_due(routes, service.clone(), hooks.clone());
    let routes = serve_apply_layout_change(routes, service.clone(), hooks.clone());
    let routes = serve_build_archive_manifest(routes, service.clone(), hooks.clone());
    let routes = serve_count_usage(routes, service.clone(), hooks.clone());
    let routes = serve_export_usage(routes, service.clone(), hooks.clone());
    let routes = serve_move_tenant(routes, service.clone(), hooks.clone());
    serve_switch_placement(routes, service, hooks)
}

