/// What the routes of component `runtime` (Runtime) need from the deployment beyond the implementation of its contracts: the hooks of every one of them.
pub trait RuntimeHooks:
    HealthCheckHooks
    + ForkTenantHooks
    + ReceiveInboundWebhookHooks
    + ListWebhookDeliveriesHooks
    + IssueSubmissionTokenHooks
    + SubmitFormHooks
    + ExportFormSubmissionsHooks
    + SaveRecordEditHooks
    + AnnouncePresenceHooks
    + UploadFileHooks
    + VerifyWebhookSignatureHooks
{
}

impl<
        T: HealthCheckHooks
            + ForkTenantHooks
            + ReceiveInboundWebhookHooks
            + ListWebhookDeliveriesHooks
            + IssueSubmissionTokenHooks
            + SubmitFormHooks
            + ExportFormSubmissionsHooks
            + SaveRecordEditHooks
            + AnnouncePresenceHooks
            + UploadFileHooks
            + VerifyWebhookSignatureHooks,
    > RuntimeHooks for T
{
}

/// Adds the route of every contract component `runtime` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn runtime_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Runtime + Send + Sync + 'static,
    H: RuntimeHooks,
{
    let routes = serve_health_check(routes, service.clone(), hooks.clone());
    let routes = serve_fork_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_receive_inbound_webhook(routes, service.clone(), hooks.clone());
    let routes = serve_list_webhook_deliveries(routes, service.clone(), hooks.clone());
    let routes = serve_issue_submission_token(routes, service.clone(), hooks.clone());
    let routes = serve_submit_form(routes, service.clone(), hooks.clone());
    let routes = serve_export_form_submissions(routes, service.clone(), hooks.clone());
    let routes = serve_save_record_edit(routes, service.clone(), hooks.clone());
    let routes = serve_announce_presence(routes, service.clone(), hooks.clone());
    let routes = serve_upload_file(routes, service.clone(), hooks.clone());
    serve_verify_webhook_signature(routes, service, hooks)
}

