/// What the routes of component `automation-worker` (Automation worker) need from the deployment beyond the implementation of its contracts: the hooks of every one of them.
pub trait AutomationWorkerHooks:
    ScheduleJobHooks
    + LeaseJobHooks
    + ReportJobResultHooks
    + CancelJobHooks
    + RetryJobHooks
    + ListJobsHooks
    + DefineScheduleHooks
    + FireTriggerHooks
    + ActivateWorkflowHooks
    + StartWorkflowRunHooks
    + AdvanceWorkflowRunHooks
    + ApproveWorkflowStepHooks
{
}

impl<
        T: ScheduleJobHooks
            + LeaseJobHooks
            + ReportJobResultHooks
            + CancelJobHooks
            + RetryJobHooks
            + ListJobsHooks
            + DefineScheduleHooks
            + FireTriggerHooks
            + ActivateWorkflowHooks
            + StartWorkflowRunHooks
            + AdvanceWorkflowRunHooks
            + ApproveWorkflowStepHooks,
    > AutomationWorkerHooks for T
{
}

/// Adds the route of every contract component `automation-worker` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn automation_worker_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::AutomationWorker + Send + Sync + 'static,
    H: AutomationWorkerHooks,
{
    let routes = serve_schedule_job(routes, service.clone(), hooks.clone());
    let routes = serve_lease_job(routes, service.clone(), hooks.clone());
    let routes = serve_report_job_result(routes, service.clone(), hooks.clone());
    let routes = serve_cancel_job(routes, service.clone(), hooks.clone());
    let routes = serve_retry_job(routes, service.clone(), hooks.clone());
    let routes = serve_list_jobs(routes, service.clone(), hooks.clone());
    let routes = serve_define_schedule(routes, service.clone(), hooks.clone());
    let routes = serve_fire_trigger(routes, service.clone(), hooks.clone());
    let routes = serve_activate_workflow(routes, service.clone(), hooks.clone());
    let routes = serve_start_workflow_run(routes, service.clone(), hooks.clone());
    let routes = serve_advance_workflow_run(routes, service.clone(), hooks.clone());
    serve_approve_workflow_step(routes, service, hooks)
}

